# Let's look for strings that might contain validation logic
import angr

proj = angr.Project('{TARGET}', auto_load_libs=False)

# Search for interesting strings in the binary
# Look for "correct", "wrong", "valid", "invalid" etc.
strings_to_find = [b'correct', b'wrong', b'valid', b'invalid', b'success', b'fail', b'flag', b'input']

found_strings = {}
for st in proj.loader.main_object.memory:
    data = proj.loader.main_object.memory.load(st, 100)
    for s in strings_to_find:
        if s in data.lower():
            found_strings[s] = (st, data)

print(f"Found strings: {list(found_strings.keys())}")

# Let's also search memory directly
mem = proj.loader.memory
for addr in range(0x438000, 0x470000, 0x1000):
    try:
        data = mem.load(addr, 0x1000)
        for s in [b'correct', b'Correct', b'CORRECT', b'wrong', b'Wrong', b'flag', b'Flag']:
            if s in data:
                print(f"Found '{s}' near {hex(addr)}")
    except:
        pass
